#include "KS/SRC/ks/VOEngine.h"

void RandomVO::init()
{
  // Setup a RandomVO
  probability = .5;
  valid = true;
  for (int i=0; i < MAX_RANDOM_SOURCES; i++) {
    sources[i] = sourcesUsed[i] = sourcesUnused[i] = NSL_INVALID_ID;
  }
  numUsedSources=0;
  numUnusedSources=0;
  totalSources=0;
  lastSource = NSL_INVALID_ID;
}
